def normalize_task_complexity(raw: object, default: str = "simple") -> str:
    value = str(raw or "").strip().lower()
    aliases = {
        "simple": "simple",
        "low": "simple",
        "basic": "simple",
        "minimal": "simple",
        "moderate": "moderate",
        "medium": "moderate",
        "mid": "moderate",
        "balanced": "moderate",
        "standard": "moderate",
        "complex": "complex",
        "high": "complex",
        "hard": "complex",
        "difficult": "complex",
        "expert": "expert",
        "advanced": "expert",
        "system": "expert",
        "system_level": "expert",
        "production": "expert",
    }
    normalized = aliases.get(value, value)
    if normalized in TASK_COMPLEXITY_LEVELS:
        return normalized
    fallback = str(default or "").strip().lower()
    if not fallback:
        return ""
    return fallback if fallback in TASK_COMPLEXITY_LEVELS else "simple"

