def parse_llm_config_profiles(config: dict, default_ollama_url: str, default_ollama_model: str) -> dict:
    model_caps_map = config.get("model_capabilities", {})
    if isinstance(model_caps_map, str):
        model_caps_map = parse_json_object(model_caps_map, {})
    if not isinstance(model_caps_map, dict):
        model_caps_map = {}

    # Reasoning metadata is kept separate from multimodal capabilities.  The
    # importer writes this map from provider model probes, and it must survive
    # a config round-trip so model-specific effort controls remain available
    # after restart.
    raw_reasoning_map = config.get(
        "model_reasoning_capabilities",
        config.get("reasoning_capabilities", {}),
    )
    if isinstance(raw_reasoning_map, str):
        raw_reasoning_map = parse_json_object(raw_reasoning_map, {})
    if not isinstance(raw_reasoning_map, dict):
        raw_reasoning_map = {}

    raw_global_caps = config.get("multimodal_capabilities", config.get("capabilities", {}))
    if isinstance(raw_global_caps, str):
        raw_global_caps = parse_json_object(raw_global_caps, {})
    if not isinstance(raw_global_caps, dict):
        raw_global_caps = {}

    raw_global_media_endpoints = config.get("media_endpoints", {})
    if isinstance(raw_global_media_endpoints, str):
        raw_global_media_endpoints = parse_json_object(raw_global_media_endpoints, {})
    if not isinstance(raw_global_media_endpoints, dict):
        raw_global_media_endpoints = {}

    def _provider_aliases(provider_key: str, provider: str) -> list[str]:
        seen: set[str] = set()
        out: list[str] = []
        for raw in (
            provider_key,
            str(provider_key or "").replace("-", "_"),
            provider,
            str(provider or "").replace("-", "_"),
            normalize_openai_compat_provider_name(provider),
        ):
            key = str(raw or "").strip()
            if not key or key in seen:
                continue
            seen.add(key)
            out.append(key)
        return out

    def build_profile_capabilities(provider_key: str, provider: str, model: str) -> dict[str, bool]:
        caps = infer_model_multimodal_capabilities(provider, model)
        if any(k in raw_global_caps for k in MEDIA_CAPABILITY_KEYS):
            caps = merge_multimodal_capabilities(caps, parse_capability_overrides(raw_global_caps))
        for alias in _provider_aliases(provider_key, provider):
            nested_global = raw_global_caps.get(alias)
            if nested_global is not None:
                caps = merge_multimodal_capabilities(caps, parse_capability_overrides(nested_global))
            direct_override = config.get(f"{alias}_capabilities")
            if direct_override is not None:
                caps = merge_multimodal_capabilities(caps, parse_capability_overrides(direct_override))
        model_override = model_caps_map.get(model) or model_caps_map.get(str(model or "").lower())
        if model_override is not None:
            caps = merge_multimodal_capabilities(caps, parse_capability_overrides(model_override))
        return caps

    def build_profile_media_endpoints(provider_key: str) -> dict[str, str]:
        out: dict[str, str] = {}
        if any(k in raw_global_media_endpoints for k in ("image", "audio", "video")):
            out.update(parse_media_endpoints(raw_global_media_endpoints))
        for alias in _provider_aliases(provider_key, provider_key):
            nested = raw_global_media_endpoints.get(alias)
            if nested is not None:
                out.update(parse_media_endpoints(nested))
            direct = config.get(f"{alias}_media_endpoints")
            if direct is not None:
                out.update(parse_media_endpoints(direct))
            for media_type in ("image", "audio", "video"):
                specific = str(config.get(f"{alias}_{media_type}_endpoint", "") or "").strip()
                if specific:
                    out[media_type] = specific
        return out

    def default_model_for_provider(provider: str) -> str:
        normalized = str(provider or "").strip().lower()
        if normalized == "ollama":
            return default_ollama_model
        defaults = {
            "openai_compat": "gpt-4o-mini",
            "siliconflow": "Qwen/Qwen3-Next-80B-A3B-Instruct",
            "vllm": "auto",
            "lmstudio": "auto",
            "anthropic": "claude-sonnet-4-20250514",
            "glm": "glm-4-flash",
            "kimi": "moonshot-v1-8k",
            "openrouter": "meta-llama/llama-3.1-8b-instruct",
            "custom_http": "custom-model",
        }
        return defaults.get(normalized, "model")

    def normalize_profile_provider(raw: str) -> str:
        value = str(raw or "").strip().lower().replace("-", "_")
        if not value:
            return ""
        if value == "ollama":
            return "ollama"
        if value == "anthropic":
            return "anthropic"
        if is_openai_like_provider(value):
            return normalize_openai_compat_provider_name(value)
        return value

    def parse_profile_headers(raw: object) -> dict:
        if isinstance(raw, dict):
            return {str(k): str(v) for k, v in raw.items()}
        if isinstance(raw, str):
            parsed = parse_json_object(raw, {})
            if isinstance(parsed, dict):
                return {str(k): str(v) for k, v in parsed.items()}
        return {}

    def parse_profile_model_settings(raw: object, model_ids: list[str] | None = None) -> dict:
        """Normalize per-model runtime settings from config without secrets."""
        if isinstance(raw, str):
            raw = parse_json_object(raw, {})
        if not isinstance(raw, dict):
            return {}
        settings: dict[str, dict] = {}
        # A flat settings object applies to the profile's default model.
        if any(key in MODEL_RUNTIME_SETTING_KEYS for key in raw):
            target = str((model_ids or [""])[0] or "").strip()
            if target:
                normalized = normalize_model_runtime_settings(raw)
                if normalized:
                    settings[target] = normalized
            return settings
        for target, value in raw.items():
            model_id = str(target or "").strip()
            if not model_id or not isinstance(value, dict):
                continue
            normalized = normalize_model_runtime_settings(value)
            if normalized:
                settings[model_id] = normalized
        return settings

    def add_profile(
        out: list[dict],
        *,
        profile_id: str,
        provider: str,
        label: str,
        model: str = "",
        models: list[str] | None = None,
        display_name: str = "",
        title: str = "",
        base_url: str = "",
        endpoint: str = "",
        api_key: str = "",
        headers: dict | None = None,
        payload_template: str = "",
        thinking_stream: bool = False,
        response_stream: bool = False,
        temperature: float = 0.2,
        request_timeout: int = DEFAULT_REQUEST_TIMEOUT,
        capabilities: dict | None = None,
        media_endpoints: dict | None = None,
        source: str = "config",
        effort: str = "",
        max_effort: str = "",
        reasoning_supported: bool | None = None,
        reasoning_style: str = "",
        model_settings: dict | None = None,
    ):
        out.append(
            {
                "id": profile_id,
                "provider": provider,
                "label": label,
                "model": (model or "").strip(),
                "models": [str(x).strip() for x in (models or []) if str(x).strip()],
                "display_name": str(display_name or label or "").strip(),
                "title": str(title or label or "").strip(),
                "base_url": (base_url or "").strip(),
                "endpoint": (endpoint or "").strip(),
                "api_key": (api_key or "").strip(),
                "headers": headers or {},
                "payload_template": payload_template or "",
                "thinking_stream": bool(thinking_stream),
                "response_stream": bool(response_stream),
                "temperature": float(temperature or 0.2),
                "request_timeout": normalize_timeout_seconds(
                    request_timeout,
                    minimum=MIN_TIMEOUT_SECONDS,
                    maximum=MAX_TIMEOUT_SECONDS,
                    fallback=DEFAULT_REQUEST_TIMEOUT,
                ),
                "capabilities": capabilities or default_multimodal_capabilities(),
                "media_endpoints": media_endpoints or {},
                "effort": str(effort or "").strip().lower(),
                "max_effort": str(max_effort or "").strip().lower(),
                "reasoning_supported": reasoning_supported,
                "reasoning_style": str(reasoning_style or "").strip().lower(),
                "model_settings": {
                    str(model_id).strip(): normalize_model_runtime_settings(values)
                    for model_id, values in (model_settings or {}).items()
                    if str(model_id).strip() and normalize_model_runtime_settings(values)
                },
                "source": source,
            }
        )

    profiles: list[dict] = []
    config_provider = normalize_profile_provider(str(config.get("provider", "")))
    provider = config_provider
    temp = float(config.get("temperature", 0.2) or 0.2)
    timeout = normalize_timeout_seconds(
        config.get("request_timeout", DEFAULT_REQUEST_TIMEOUT),
        minimum=MIN_TIMEOUT_SECONDS,
        maximum=MAX_TIMEOUT_SECONDS,
        fallback=DEFAULT_REQUEST_TIMEOUT,
    )
    # Global effort default + ceiling (per-profile fields override these).
    effort_default = str(config.get("effort", "") or "").strip().lower()
    max_effort_default = str(config.get("max_effort", "") or "").strip().lower()
    thinking_stream_default = bool(
        config.get("thinking_stream", config.get("stream_thinking", False))
    )
    response_stream_default = bool(
        config.get("response_stream", config.get("stream_response", False))
    )
    explicit_default_profile_id = sanitize_profile_id(
        str(
            config.get("default_profile_id")
            or config.get("active_profile_id")
            or config.get("selected_profile_id")
            or ""
        )
    )
    explicit_default_candidates: list[str] = []

    raw_profiles = (
        config.get("profiles")
        if config.get("profiles") is not None
        else config.get("model_profiles")
        if config.get("model_profiles") is not None
        else config.get("llm_profiles")
        if config.get("llm_profiles") is not None
        else config.get("llms")
    )
    explicit_rows: list[dict] = []
    if isinstance(raw_profiles, dict):
        for key, value in raw_profiles.items():
            if not isinstance(value, dict):
                continue
            row = dict(value)
            row.setdefault("id", key)
            explicit_rows.append(row)
    elif isinstance(raw_profiles, list):
        for value in raw_profiles:
            if isinstance(value, dict):
                explicit_rows.append(dict(value))

    for idx, raw_profile in enumerate(explicit_rows):
        provider_hint = (
            raw_profile.get("provider")
            or raw_profile.get("vendor")
            or raw_profile.get("type")
            or raw_profile.get("kind")
            or ""
        )
        provider = normalize_profile_provider(str(provider_hint or ""))
        if not provider:
            inferred = (
                raw_profile.get("id")
                or raw_profile.get("profile_id")
                or raw_profile.get("name")
                or raw_profile.get("label")
                or ""
            )
            provider = normalize_profile_provider(str(inferred or ""))
        base_hint = str(
            raw_profile.get("base_url")
            or raw_profile.get("url")
            or raw_profile.get("api_base")
            or raw_profile.get("api_url")
            or raw_profile.get("host")
            or raw_profile.get("endpoint")
            or ""
        ).strip()
        endpoint = str(
            raw_profile.get("endpoint")
            or raw_profile.get("chat_endpoint")
            or raw_profile.get("completion_endpoint")
            or ""
        ).strip()
        if not provider and (base_hint or endpoint):
            provider = "openai_compat"
        # Arbitrary provider names are transported through the custom HTTP
        # adapter while preserving the user supplied name for display.
        provider_name = str(provider_hint or "").strip()
        if provider and provider not in {"ollama", "anthropic", "custom_http"} and not is_openai_like_provider(provider) and (base_hint or endpoint):
            provider_name = provider_name or provider
            provider = "custom_http"
        if not provider:
            continue
        profile_id = sanitize_profile_id(
            str(
                raw_profile.get("id")
                or raw_profile.get("profile_id")
                or raw_profile.get("name")
                or raw_profile.get("label")
                or raw_profile.get("title")
                or f"profile-{idx+1}"
            )
        )
        label = str(
            raw_profile.get("label")
            or raw_profile.get("custom_name")
            or raw_profile.get("name")
            or raw_profile.get("title")
            or raw_profile.get("custom_title")
            or raw_profile.get("display_name")
            or provider_name
            or profile_id
        ).strip() or profile_id
        model = str(
            raw_profile.get("model")
            or raw_profile.get("model_name")
            or raw_profile.get("default_model")
            or ""
        ).strip()
        raw_models = raw_profile.get("models", raw_profile.get("model_ids", raw_profile.get("available_models", [])))
        if isinstance(raw_models, str):
            raw_models = [x.strip() for x in re.split(r"[,\n]", raw_models) if x.strip()]
        if not isinstance(raw_models, list):
            raw_models = []
        model_settings: dict[str, dict] = {}
        model_values: list[str] = []
        for value in raw_models:
            if isinstance(value, dict):
                model_id = str(value.get("id") or value.get("model") or value.get("name") or "").strip()
                if not model_id:
                    continue
                model_values.append(model_id)
                inline_settings = normalize_model_runtime_settings(value)
                if inline_settings:
                    model_settings[model_id] = inline_settings
            elif str(value).strip():
                model_values.append(str(value).strip())
        models = list(dict.fromkeys(model_values))
        if model and model not in models:
            models.insert(0, model)
        if not model:
            # A supplied model directory is already authoritative.  Do not
            # prepend a synthetic provider default such as ``custom-model``.
            model = models[0] if models else default_model_for_provider(provider)
        model_settings.update(parse_profile_model_settings(raw_profile.get("model_settings"), [model] + models))
        base_url = extract_base_url(base_hint or endpoint)
        if provider == "ollama" and not base_url:
            base_url = extract_base_url(default_ollama_url)
        api_key = str(
            raw_profile.get("api_key")
            or raw_profile.get("key")
            or raw_profile.get("token")
            or ""
        ).strip()
        headers = parse_profile_headers(raw_profile.get("headers"))
        payload_template = str(
            raw_profile.get("payload_template")
            or raw_profile.get("payload")
            or raw_profile.get("template")
            or ""
        ).strip()
        if provider == "anthropic":
            anth_base = base_url or "https://api.anthropic.com"
            endpoint = endpoint or anth_base.rstrip("/") + "/v1/messages"
            base_url = extract_base_url(anth_base)
        elif is_openai_like_provider(provider):
            endpoint = endpoint or complete_chat_endpoint(base_url)
        caps_key = str(raw_profile.get("capabilities_key") or profile_id or provider)
        capabilities = build_profile_capabilities(caps_key, provider, model)
        if raw_profile.get("capabilities") is not None:
            capabilities = merge_multimodal_capabilities(
                capabilities,
                parse_capability_overrides(raw_profile.get("capabilities")),
            )
        media_endpoints = build_profile_media_endpoints(caps_key)
        if raw_profile.get("media_endpoints") is not None:
            media_endpoints.update(parse_media_endpoints(raw_profile.get("media_endpoints")))
        for media_type in ("image", "audio", "video"):
            specific = str(
                raw_profile.get(f"{media_type}_endpoint")
                or raw_profile.get(f"{media_type}_url")
                or ""
            ).strip()
            if specific:
                media_endpoints[media_type] = specific
        add_profile(
            profiles,
            profile_id=profile_id,
            provider=provider,
            label=label,
            model=model,
            models=models,
            display_name=str(
                raw_profile.get("display_name")
                or raw_profile.get("provider_name")
                or raw_profile.get("custom_name")
                or (raw_profile.get("name") if provider == "custom_http" else "")
                or (provider_name if provider_name and provider_name.lower() not in {"custom_http", "openai_compat"} else "")
                or label
            ),
            title=str(
                raw_profile.get("title")
                or raw_profile.get("custom_title")
                or label
            ),
            base_url=base_url,
            endpoint=endpoint,
            api_key=api_key,
            headers=headers,
            payload_template=payload_template,
            thinking_stream=bool(
                raw_profile.get(
                    "thinking_stream",
                    raw_profile.get(
                        "stream_thinking",
                        raw_profile.get("thinking", thinking_stream_default),
                    ),
                )
            ),
            response_stream=bool(
                raw_profile.get(
                    "response_stream",
                    raw_profile.get("stream_response", response_stream_default),
                )
            ),
            temperature=float(raw_profile.get("temperature", temp) or temp),
            request_timeout=raw_profile.get("request_timeout", timeout),
            capabilities=capabilities,
            media_endpoints=media_endpoints,
            effort=str(raw_profile.get("effort", effort_default) or effort_default),
            max_effort=str(raw_profile.get("max_effort", max_effort_default) or max_effort_default),
            reasoning_supported=(raw_profile.get("reasoning_supported") if isinstance(raw_profile.get("reasoning_supported"), bool) else None),
            reasoning_style=str(raw_profile.get("reasoning_style") or raw_profile.get("reasoning_dialect") or ""),
            model_settings=model_settings,
            source=str(raw_profile.get("source", "profiles") or "profiles"),
        )
        if bool(raw_profile.get("default")) or bool(raw_profile.get("active")) or bool(raw_profile.get("selected")):
            explicit_default_candidates.append(profile_id)

    ollama_requested = bool(
        provider == "ollama"
        or str(config.get("ollama_url", "")).strip()
        or str(config.get("ollama_model", "")).strip()
    )
    ollama_url = str(config.get("ollama_url", default_ollama_url)).strip() or default_ollama_url
    ollama_model = str(config.get("ollama_model", default_ollama_model)).strip() or default_ollama_model
    if ollama_requested:
        add_profile(
            profiles,
            profile_id="ollama",
            provider="ollama",
            label="Ollama",
            model=ollama_model,
            base_url=extract_base_url(ollama_url),
            thinking_stream=bool(config.get("ollama_thinking_stream", thinking_stream_default)),
            response_stream=bool(config.get("ollama_response_stream", response_stream_default)),
            temperature=temp,
            request_timeout=timeout,
            capabilities=build_profile_capabilities("ollama", "ollama", ollama_model),
            media_endpoints=build_profile_media_endpoints("ollama"),
        )

    openai_url = str(config.get("openai_url", "")).strip()
    openai_model = str(config.get("openai_model", "")).strip()
    openai_key = str(config.get("openai_key", "")).strip()
    if openai_url or openai_model or openai_key:
        add_profile(
            profiles,
            profile_id="openai",
            provider=normalize_profile_provider("openai"),
            label="OpenAI Compatible",
            model=openai_model or "gpt-4o-mini",
            base_url=extract_base_url(openai_url),
            endpoint=complete_chat_endpoint(openai_url),
            api_key=openai_key,
            thinking_stream=bool(config.get("openai_thinking_stream", thinking_stream_default)),
            response_stream=bool(config.get("openai_response_stream", response_stream_default)),
            temperature=temp,
            request_timeout=timeout,
            capabilities=build_profile_capabilities("openai", normalize_profile_provider("openai"), openai_model or "gpt-4o-mini"),
            media_endpoints=build_profile_media_endpoints("openai"),
        )

    sf_url = str(config.get("siliconflow_url", "")).strip()
    sf_model = str(config.get("siliconflow_model", "")).strip()
    sf_key = str(config.get("siliconflow_key", "")).strip()
    if sf_url or sf_model or sf_key:
        add_profile(
            profiles,
            profile_id="siliconflow",
            provider=normalize_profile_provider("siliconflow"),
            label="SiliconFlow",
            model=sf_model or "Qwen/Qwen3-Next-80B-A3B-Instruct",
            base_url=extract_base_url(sf_url),
            endpoint=complete_chat_endpoint(sf_url),
            api_key=sf_key,
            thinking_stream=bool(config.get("siliconflow_thinking_stream", thinking_stream_default)),
            response_stream=bool(config.get("siliconflow_response_stream", response_stream_default)),
            temperature=temp,
            request_timeout=timeout,
            capabilities=build_profile_capabilities("siliconflow", normalize_profile_provider("siliconflow"), sf_model or "Qwen/Qwen3-Next-80B-A3B-Instruct"),
            media_endpoints=build_profile_media_endpoints("siliconflow"),
        )

    # ── vLLM (local) ──────────────────────────────────────────────
    vllm_url = str(config.get("vllm_url", "")).strip()
    vllm_model = str(config.get("vllm_model", "")).strip()
    vllm_key = str(config.get("vllm_key", "")).strip()
    if vllm_url or vllm_model:
        _vllm_default = "http://localhost:8000/v1"
        add_profile(
            profiles,
            profile_id="vllm",
            provider=normalize_profile_provider("vllm"),
            label="vLLM",
            model=vllm_model or "auto",
            base_url=extract_base_url(vllm_url or _vllm_default),
            endpoint=complete_chat_endpoint(vllm_url or _vllm_default),
            api_key=vllm_key,
            thinking_stream=bool(config.get("vllm_thinking_stream", thinking_stream_default)),
            response_stream=bool(config.get("vllm_response_stream", response_stream_default)),
            temperature=temp,
            request_timeout=timeout,
            capabilities=build_profile_capabilities("vllm", normalize_profile_provider("vllm"), vllm_model or "auto"),
            media_endpoints=build_profile_media_endpoints("vllm"),
        )

    # ── LM Studio (local) ─────────────────────────────────────────
    lms_url = str(config.get("lmstudio_url", "")).strip()
    lms_model = str(config.get("lmstudio_model", "")).strip()
    if lms_url or lms_model:
        _lms_default = "http://localhost:1234/v1"
        add_profile(
            profiles,
            profile_id="lmstudio",
            provider=normalize_profile_provider("lmstudio"),
            label="LM Studio",
            model=lms_model or "auto",
            base_url=extract_base_url(lms_url or _lms_default),
            endpoint=complete_chat_endpoint(lms_url or _lms_default),
            thinking_stream=bool(config.get("lmstudio_thinking_stream", thinking_stream_default)),
            response_stream=bool(config.get("lmstudio_response_stream", response_stream_default)),
            temperature=temp,
            request_timeout=timeout,
            capabilities=build_profile_capabilities("lmstudio", normalize_profile_provider("lmstudio"), lms_model or "auto"),
            media_endpoints=build_profile_media_endpoints("lmstudio"),
        )

    # ── Anthropic ──────────────────────────────────────────────────
    anth_url = str(config.get("anthropic_url", "")).strip()
    anth_model = str(config.get("anthropic_model", "")).strip()
    anth_key = str(config.get("anthropic_key", "")).strip()
    if anth_url or anth_model or anth_key:
        _anth_base = anth_url or "https://api.anthropic.com"
        add_profile(
            profiles,
            profile_id="anthropic",
            provider="anthropic",
            label="Anthropic",
            model=anth_model or "claude-sonnet-4-20250514",
            base_url=extract_base_url(_anth_base),
            endpoint=_anth_base.rstrip("/") + "/v1/messages",
            api_key=anth_key,
            thinking_stream=bool(config.get("anthropic_thinking_stream", thinking_stream_default)),
            response_stream=bool(config.get("anthropic_response_stream", response_stream_default)),
            temperature=temp,
            request_timeout=timeout,
            capabilities=build_profile_capabilities("anthropic", "anthropic", anth_model or "claude-sonnet-4-20250514"),
            media_endpoints=build_profile_media_endpoints("anthropic"),
        )

    # ── GLM (智谱) ─────────────────────────────────────────────────
    glm_url = str(config.get("glm_url", "")).strip()
    glm_model = str(config.get("glm_model", "")).strip()
    glm_key = str(config.get("glm_key", "")).strip()
    if glm_url or glm_model or glm_key:
        _glm_default = "https://open.bigmodel.cn/api/paas/v4"
        add_profile(
            profiles,
            profile_id="glm",
            provider=normalize_profile_provider("glm"),
            label="GLM",
            model=glm_model or "glm-4-flash",
            base_url=extract_base_url(glm_url or _glm_default),
            endpoint=complete_chat_endpoint(glm_url or _glm_default),
            api_key=glm_key,
            thinking_stream=bool(config.get("glm_thinking_stream", thinking_stream_default)),
            response_stream=bool(config.get("glm_response_stream", response_stream_default)),
            temperature=temp,
            request_timeout=timeout,
            capabilities=build_profile_capabilities("glm", normalize_profile_provider("glm"), glm_model or "glm-4-flash"),
            media_endpoints=build_profile_media_endpoints("glm"),
            effort=str(config.get("glm_effort", effort_default) or effort_default),
            max_effort=str(config.get("glm_max_effort", max_effort_default) or max_effort_default),
        )

    # ── KIMI (Moonshot / 月之暗面) ─────────────────────────────────
    kimi_url = str(config.get("kimi_url", "")).strip()
    kimi_model = str(config.get("kimi_model", "")).strip()
    kimi_key = str(config.get("kimi_key", "")).strip()
    if kimi_url or kimi_model or kimi_key:
        _kimi_default = "https://api.moonshot.cn/v1"
        add_profile(
            profiles,
            profile_id="kimi",
            provider=normalize_profile_provider("kimi"),
            label="KIMI (Moonshot)",
            model=kimi_model or "moonshot-v1-8k",
            base_url=extract_base_url(kimi_url or _kimi_default),
            endpoint=complete_chat_endpoint(kimi_url or _kimi_default),
            api_key=kimi_key,
            thinking_stream=bool(config.get("kimi_thinking_stream", thinking_stream_default)),
            response_stream=bool(config.get("kimi_response_stream", response_stream_default)),
            temperature=temp,
            request_timeout=timeout,
            capabilities=build_profile_capabilities("kimi", normalize_profile_provider("kimi"), kimi_model or "moonshot-v1-8k"),
            media_endpoints=build_profile_media_endpoints("kimi"),
        )

    # ── OpenRouter ─────────────────────────────────────────────────
    or_url = str(config.get("openrouter_url", "")).strip()
    or_model = str(config.get("openrouter_model", "")).strip()
    or_key = str(config.get("openrouter_key", "")).strip()
    if or_url or or_model or or_key:
        _or_default = "https://openrouter.ai/api/v1"
        add_profile(
            profiles,
            profile_id="openrouter",
            provider=normalize_profile_provider("openrouter"),
            label="OpenRouter",
            model=or_model or "meta-llama/llama-3.1-8b-instruct",
            base_url=extract_base_url(or_url or _or_default),
            endpoint=complete_chat_endpoint(or_url or _or_default),
            api_key=or_key,
            thinking_stream=bool(config.get("openrouter_thinking_stream", thinking_stream_default)),
            response_stream=bool(config.get("openrouter_response_stream", response_stream_default)),
            temperature=temp,
            request_timeout=timeout,
            capabilities=build_profile_capabilities("openrouter", normalize_profile_provider("openrouter"), or_model or "meta-llama/llama-3.1-8b-instruct"),
            media_endpoints=build_profile_media_endpoints("openrouter"),
        )

    custom_url = str(
        config.get("custom_url")
        or (config.get("provider_url") if config_provider == "custom_http" else "")
        or (config.get("url") if config_provider == "custom_http" else "")
        or ""
    ).strip()
    custom_key = str(config.get("custom_key", "")).strip()
    custom_headers = parse_json_object(str(config.get("custom_headers", "{}") or "{}"), {})
    custom_payload = str(config.get("custom_payload", "") or "").strip()
    if custom_url:
        raw_custom_models = config.get(
            "custom_models",
            config.get(
                "custom_model_ids",
                config.get("models", []) if config_provider == "custom_http" else [],
            ),
        )
        if isinstance(raw_custom_models, str):
            raw_custom_models = [x.strip() for x in re.split(r"[,\n]", raw_custom_models) if x.strip()]
        custom_models = [str(x).strip() for x in raw_custom_models] if isinstance(raw_custom_models, list) else []
        custom_model = str(
            config.get("custom_model", "")
            or (config.get("model", "") if config_provider == "custom_http" else "")
            or config.get("openai_model", "")
        ).strip()
        if not custom_model and custom_models:
            custom_model = custom_models[0]
        if not custom_model:
            custom_model = "custom-model"
        if custom_model and custom_model not in custom_models:
            custom_models.insert(0, custom_model)
        add_profile(
            profiles,
            profile_id="custom",
            provider=normalize_profile_provider("custom_http"),
            label=str(
                config.get("custom_name")
                or (config.get("provider_name") if config_provider == "custom_http" else "")
                or config.get("custom_title")
                or "Custom HTTP"
            ),
            model=custom_model,
            models=custom_models,
            display_name=str(
                config.get("custom_name")
                or (config.get("provider_name") if config_provider == "custom_http" else "")
                or "Custom HTTP"
            ),
            title=str(
                config.get("custom_title")
                or (config.get("provider_title") if config_provider == "custom_http" else "")
                or config.get("custom_name")
                or "Custom HTTP"
            ),
            base_url=extract_base_url(custom_url),
            endpoint=custom_url,
            api_key=custom_key,
            headers=custom_headers,
            payload_template=custom_payload,
            thinking_stream=bool(config.get("custom_thinking_stream", thinking_stream_default)),
            response_stream=bool(config.get("custom_response_stream", response_stream_default)),
            temperature=temp,
            request_timeout=timeout,
            capabilities=build_profile_capabilities("custom", normalize_profile_provider("custom_http"), str(config.get("custom_model", "") or config.get("openai_model", "") or "custom-model")),
            media_endpoints=build_profile_media_endpoints("custom"),
        )

    if not profiles:
        add_profile(
            profiles,
            profile_id="ollama",
            provider="ollama",
            label="Ollama",
            model=default_ollama_model,
            base_url=default_ollama_url,
            thinking_stream=thinking_stream_default,
            response_stream=response_stream_default,
            temperature=0.2,
            request_timeout=DEFAULT_REQUEST_TIMEOUT,
            capabilities=build_profile_capabilities("ollama", "ollama", default_ollama_model),
            media_endpoints=build_profile_media_endpoints("ollama"),
            source="default",
        )

    # Legacy provider keys may carry a comma/newline separated model list.
    # Keep the configured default first, then let the catalog append probed
    # models without creating duplicate profiles.
    provider_model_keys = {
        "ollama": "ollama_models", "openai_compat": "openai_models",
        "siliconflow": "siliconflow_models", "vllm": "vllm_models",
        "lmstudio": "lmstudio_models", "anthropic": "anthropic_models",
        "glm": "glm_models", "kimi": "kimi_models", "openrouter": "openrouter_models",
        "custom_http": "custom_models",
    }
    for profile in profiles:
        prov = str(profile.get("provider", "") or "").lower()
        model_list_key = provider_model_keys.get(prov, "")
        raw_list = (
            config.get(
                model_list_key,
                config.get("models", []) if config_provider == prov else [],
            )
            if model_list_key
            else []
        )
        if isinstance(raw_list, str):
            raw_list = [x.strip() for x in re.split(r"[,\n]", raw_list) if x.strip()]
        existing = [str(x).strip() for x in profile.get("models", []) if str(x).strip()]
        if not existing and isinstance(raw_list, list):
            existing = [str(x).strip() for x in raw_list if str(x).strip()]
        default_model = str(profile.get("model", "") or "").strip()
        # ``auto`` is a transport placeholder for local OpenAI-compatible
        # servers.  Once a model directory is available, make its first
        # discovered entry the active model so importing a directory is
        # immediately runnable and stable across restarts.
        if existing and default_model.lower() == "auto":
            default_model = existing[0]
            profile["model"] = default_model
        if default_model and default_model not in existing:
            existing.insert(0, default_model)
        profile["models"] = existing

    active_map = {
        "ollama": "ollama",
        "openai": "openai",
        "siliconflow": "siliconflow",
        "vllm": "vllm",
        "lmstudio": "lmstudio",
        "anthropic": "anthropic",
        "glm": "glm",
        "kimi": "kimi",
        "openrouter": "openrouter",
        "custom": "custom",
    }
    profile_ids = {p["id"] for p in profiles}
    default_profile_id = explicit_default_profile_id if explicit_default_profile_id in profile_ids else ""
    if (not default_profile_id) and explicit_default_candidates:
        for candidate in explicit_default_candidates:
            if candidate in profile_ids:
                default_profile_id = candidate
                break
    if not default_profile_id:
        default_profile_id = active_map.get(config_provider or provider, "")
    if not default_profile_id or default_profile_id not in profile_ids:
        # Fallback: first non-ollama profile that was explicitly configured
        for p in profiles:
            if p["id"] != "ollama" and p.get("source") != "default":
                default_profile_id = p["id"]
                break
        if not default_profile_id or default_profile_id not in profile_ids:
            default_profile_id = profiles[0]["id"]
    # Apply global effort / max_effort to any profile that did not set its own
    # (only the structured-profiles path and the GLM simple schema read these
    # inline; this post-pass makes the config-level effort apply to EVERY
    # provider uniformly). Per-profile values already set are preserved.
    if effort_default or max_effort_default:
        for p in profiles:
            if effort_default and not str(p.get("effort", "") or "").strip():
                p["effort"] = effort_default
            if max_effort_default and not str(p.get("max_effort", "") or "").strip():
                p["max_effort"] = max_effort_default
    raw_runtime_settings = config.get(
        "model_settings",
        config.get("model_runtime_settings", config.get("runtime_settings", {})),
    )
    if isinstance(raw_runtime_settings, str):
        raw_runtime_settings = parse_json_object(raw_runtime_settings, {})
    if isinstance(raw_runtime_settings, dict):
        for profile in profiles:
            current = dict(profile.get("model_settings", {}) or {})
            profile_model = str(profile.get("model", "") or "").strip()
            provider_id = str(profile.get("id", "") or "").strip()
            provider_name = str(profile.get("provider", "") or "").strip()
            for model_id, value in raw_reasoning_map.items():
                normalized = normalize_model_runtime_settings(value)
                target = str(model_id or "").strip()
                if target and normalized:
                    current[target] = {**current.get(target, {}), **normalized}
            for key in (profile_model, provider_id, provider_name):
                value = raw_runtime_settings.get(key) if key else None
                if isinstance(value, dict) and any(k in MODEL_RUNTIME_SETTING_KEYS for k in value):
                    normalized = normalize_model_runtime_settings(value)
                    if profile_model and normalized:
                        current[profile_model] = {**current.get(profile_model, {}), **normalized}
            for model_id, value in raw_runtime_settings.items():
                if not isinstance(value, dict):
                    continue
                normalized = normalize_model_runtime_settings(value)
                if normalized:
                    current[str(model_id).strip()] = {**current.get(str(model_id).strip(), {}), **normalized}
                elif str(model_id) in {provider_id, provider_name}:
                    for nested_model, nested_value in value.items():
                        nested = normalize_model_runtime_settings(nested_value)
                        if nested:
                            target = str(nested_model or "").strip()
                            current[target] = {**current.get(target, {}), **nested}
            profile["model_settings"] = current
    elif raw_reasoning_map:
        for profile in profiles:
            current = dict(profile.get("model_settings", {}) or {})
            for model_id, value in raw_reasoning_map.items():
                target = str(model_id or "").strip()
                normalized = normalize_model_runtime_settings(value)
                if target and normalized:
                    current[target] = {**current.get(target, {}), **normalized}
            profile["model_settings"] = current
    return {"profiles": profiles, "default_profile_id": default_profile_id}

