        "glm_max_effort",
        "kimi_url",
        "kimi_model",
        "kimi_key",
        "openrouter_url",
        "openrouter_model",
        "openrouter_key",
        "custom_url",
        "provider_url",
        "provider_name",
        "provider_title",
        "name",
        "title",
        "custom_name",
        "custom_title",
        "custom_model",
        "custom_models",
        "custom_key",
        "custom_headers",
        "custom_payload",
        "capabilities",
        "multimodal_capabilities",
        "model_capabilities",
        "model_reasoning_capabilities",
        "reasoning_capabilities",
        "media_endpoints",
        "ollama_capabilities",
        "openai_capabilities",
        "siliconflow_capabilities",
        "anthropic_capabilities",
        "glm_capabilities",
        "kimi_capabilities",
        "openrouter_capabilities",
        "vllm_capabilities",
        "lmstudio_capabilities",
        "custom_capabilities",
        "ollama_media_endpoints",
        "openai_media_endpoints",
        "siliconflow_media_endpoints",
        "custom_media_endpoints",
        "ollama_image_endpoint",
        "ollama_audio_endpoint",
        "ollama_video_endpoint",
        "openai_image_endpoint",
        "openai_audio_endpoint",
